        "why_flagged": null,
        "legal_reference": "\u0627\u0644\u0645\u0627\u062F\u0629 558 \u0645\u0646 \u0627\u0644\u0642\u0627\u0646\u0648\u0646 \u0627\u0644\u0645\u062F\u0646\u064A \u0627\u0644\u0645\u0635\u0631\u064A: \u062A\u064F\u0639\u0631\u0651\u0641 \u0639\u0642\u062F \u0627\u0644\u0625\u064A\u062C\u0627\u0631 \u0628\u0623\u0646\u0647 \u0627\u0644\u062A\u0632\u0627\u0645 \u0627\u0644\u0645\u0624\u062C\u0631 \u0628\u062A\u0645\u0643\u064A\u0646 \u0627\u0644\u0645\u0633\u062A\u0623\u062C\u0631 \u0645\u0646 \u0627\u0644\u0627\u0646\u062A\u0641\u0627\u0639 \u0628\u0634\u064A\u0621 \u0645\u0639\u064A\u0646 \u0645\u062F\u0629 \u0645\u0639\u064A\u0646\u0629 \u0644\u0642\u0627\u0621 \u0623\u062C\u0631 \u0645\u0639\u0644\u0648\u0645\u060C \u0648\u062A\u0639\u062A\u0628\u0631 \u0627\u0644\u0645\u062F\u0629 \u0631\u0643\u0646\u064B\u0627 \u062C\u0648\u0647\u0631\u064A\u064B\u0627 \u0641\u064A \u0627\u0644\u0639\u0642\u062F.",
