        "clause_pattern": "\u064A\u062D\u0642 \u0644\u0644\u0645\u0627\u0644\u0643 \u062F\u062E\u0648\u0644 \u0627\u0644\u0639\u0642\u0627\u0631 \u0623\u0648 \u062A\u063A\u064A\u064A\u0631 \u0627\u0644\u0623\u0642\u0641\u0627\u0644 \u062F\u0648\u0646 \u0625\u0630\u0646 \u0627\u0644\u0645\u0633\u062A\u0623\u062C\u0631 \u0641\u064A \u062D\u0627\u0644\u0629 \u0627\u0644\u062A\u0623\u062E\u0631 \u0641\u064A \u0627\u0644\u0633\u062F\u0627\u062F",
        "risk_level": "attention",
        "risk_color": "red",
        "explanation": "\u0647\u0630\u0627 \u0627\u0644\u0628\u0646\u062F \u063A\u064A\u0631 \u0642\u0627\u0646\u0648\u0646\u064A \u0639\u0645\u0644\u064A\u064B\u0627\u061B \u0641\u0644\u0627 \u064A\u062C\u0648\u0632 \u0644\u0644\u0645\u0627\u0644\u0643 \u0627\u062A\u062E\u0627\u0630 \u0625\u062C\u0631\u0627\u0621\u0627\u062A \u0641\u0631\u062F\u064A\u0629 \u0643\u062A\u063A\u064A\u064A\u0631 \u0627\u0644\u0623\u0642\u0641\u0627\u0644 \u0623\u0648 \u0627\u0644\u0625\u062E\u0644\u0627\u0621 \u0628\u0627\u0644\u0642\u0648\u0629\u060C \u0648\u064A\u062C\u0628 \u0627\u0644\u0644\u062C\u0648\u0621 \u0644\u0644\u0637\u0631\u0642 \u0627\u0644\u0642\u0627\u0646\u0648\u0646\u064A\u0629 \u0648\u0627\u0644\u0642\u0636\u0627\u0626\u064A\u0629 \u062F\u0627\u0626\u0645\u064B\u0627.",
        "why_flagged": "\u0627\u0644\u0625\u062E\u0644\u0627\u0621 \u0628\u0627\u0644\u0642\u0648\u0629 \u0623\u0648 \u0628\u0637\u0631\u0642 \u063A\u064A\u0631 \u0642\u0627\u0646\u0648\u0646\u064A\u0629 \u0645\u062E\u0627\u0644\u0641 \u0644\u0644\u0642\u0627\u0646\u0648\u0646 \u0628\u0635\u0631\u0641 \u0627\u0644\u0646\u0638\u0631 \u0639\u0646 \u0646\u0635 \u0627\u0644\u0639\u0642\u062F.",
        "legal_reference": "\u0644\u0627 \u064A\u062C\u0648\u0632 \u0627\u0644\u062A\u0646\u0641\u064A\u0630 \u0627\u0644\u0630\u0627\u062A\u064A (\u0623\u062E\u0630 \u0627\u0644\u062D\u0642 \u0628\u0627\u0644\u064A\u062F) \u0641\u064A \u0627\u0644\u0642\u0627\u0646\u0648\u0646 \u0627\u0644\u0645\u0635\u0631\u064A\u061B \u064A\u062C\u0628 \u0627\u0644\u0644\u062C\u0648\u0621 \u0625\u0644\u0649 \u0627\u0644\u0642\u0636\u0627\u0621 \u0644\u0627\u0633\u062A\u0635\u062F\u0627\u0631 \u062D\u0643\u0645 \u0628\u0627\u0644\u0625\u062E\u0644\u0627\u0621 \u0648\u062A\u0646\u0641\u064A\u0630\u0647 \u0639\u0628\u0631 \u0627\u0644\u062C\u0647\u0627\u062A \u0627\u0644\u0631\u0633\u0645\u064A\u0629 \u0627\u0644\u0645\u062E\u062A\u0635\u0629\u060C \u0648\u0644\u0627 \u064A\u064F\u0639\u062A\u062F \u0628\u0623\u064A \u0634\u0631\u0637 \u062A\u0639\u0627\u0642\u062F\u064A \u064A\u062E\u0627\u0644\u0641 \u0630\u0644\u0643.",
