        "why_flagged": "\u0625\u0633\u0642\u0627\u0637 \u0627\u0644\u0636\u0645\u0627\u0646 \u0627\u0644\u0643\u0627\u0645\u0644 \u0642\u062F \u064A\u064F\u0633\u062A\u062E\u062F\u0645 \u0644\u0625\u062E\u0641\u0627\u0621 \u0623\u0639\u0637\u0627\u0644 \u062D\u0642\u064A\u0642\u064A\u0629 \u0645\u0639\u0631\u0648\u0641\u0629 \u0644\u0644\u0628\u0627\u0626\u0639.",
        "legal_reference": "\u0627\u0644\u0645\u0627\u062F\u0629 453 \u0645\u0646 \u0627\u0644\u0642\u0627\u0646\u0648\u0646 \u0627\u0644\u0645\u062F\u0646\u064A \u0627\u0644\u0645\u0635\u0631\u064A: \u064A\u062C\u0648\u0632 \u0644\u0644\u0645\u062A\u0639\u0627\u0642\u062F\u064A\u0646 \u0627\u0644\u0627\u062A\u0641\u0627\u0642 \u0639\u0644\u0649 \u0632\u064A\u0627\u062F\u0629 \u0627\u0644\u0636\u0645\u0627\u0646 \u0623\u0648 \u0625\u0646\u0642\u0627\u0635\u0647 \u0623\u0648 \u0625\u0633\u0642\u0627\u0637\u0647\u060C \u0644\u0643\u0646 \u064A\u0642\u0639 \u0628\u0627\u0637\u0644\u064B\u0627 \u0623\u064A \u0634\u0631\u0637 \u064A\u0633\u0642\u0637 \u0627\u0644\u0636\u0645\u0627\u0646 \u0625\u0630\u0627 \u0643\u0627\u0646 \u0627\u0644\u0628\u0627\u0626\u0639 \u0642\u062F \u062A\u0639\u0645\u062F \u0625\u062E\u0641\u0627\u0621 \u0627\u0644\u0639\u064A\u0628 \u063A\u0634\u064B\u0627 \u0645\u0646\u0647.",
