        "topic": "\u0633\u0644\u0637\u0629 \u0627\u0644\u0642\u0627\u0636\u064A \u0641\u064A \u062A\u0639\u062F\u064A\u0644 \u0627\u0644\u0634\u0631\u0648\u0637 \u0627\u0644\u062A\u0639\u0633\u0641\u064A\u0629",
