// server/lib/gemini.ts
var ai = null;
var GoogleGenAIClass = null;
function model() {
  return GEMINI_MODEL || "gemini-2.5-flash";
}
async function getClient() {
  if (!ai) {
    const key = GEMINI_API_KEY || process.env.GEMINI_API_KEY;
    if (key && key !== "YOUR_GEMINI_API_KEY_HERE") {
      if (!GoogleGenAIClass) {
        const mod = await import("@google/genai");
        GoogleGenAIClass = mod.GoogleGenAI;
      }
      ai = new GoogleGenAIClass({ apiKey: key });
    } else {
      throw new Error("Gemini client not initialized. Set GEMINI_API_KEY in server/config.ts or via environment variables.");
    }
  }
  return ai;
}
async function askDocument(input) {
  const client = await getClient();
  const contents = input.history.map((message) => ({
    role: message.role === "user" ? "user" : "model",
    parts: [{ text: message.text }]
  }));
  contents.push({
    role: "user",
    parts: [
      {
        text: buildAskUserPrompt({
          documentText: input.documentText,
          documentType: input.documentType,
          groundContext: input.groundContext,
          question: input.question
        })
      }
    ]
  });
  const response = await client.models.generateContent({
    model: model(),
    contents,
    config: {
      systemInstruction: ASK_SYSTEM_INSTRUCTION,
      maxOutputTokens: 8192
    }
  });
  const text = response.text;
  if (!text) {
    throw new Error("Gemini returned an empty answer.");
  }
  return text.trim();
}

// server/lib/ruleEngine.ts
function askDocumentLocal(input) {
  const q = (input.question || "").trim().toLowerCase();
  const text = input.documentText || "";
  const kb2 = getKnowledgeBase();
  const qKeywords = q.split(/\s+/).map((w) => w.replace(/[^\u0621-\u064A]/g, "")).filter((w) => w.length > 2);
  const sentences = text.split(/(?:\r?\n)+|(?<=[.؛!\?])\s+/).filter((s) => s.trim().length > 10);
  let bestSentence = "";
  let maxScore = 0;
  for (const sentence of sentences) {
    const score = qKeywords.reduce((acc, kw) => sentence.includes(kw) ? acc + 1 : acc, 0);
    if (score > maxScore) {
      maxScore = score;
      bestSentence = sentence.trim();
    }
  }
  const catData = kb2[input.documentType];
  let relevantLegalRef = "";
  let relevantExplanation = "";
  if (catData && Array.isArray(catData.clauses)) {
    for (const cl of catData.clauses) {
      const p = `${cl.category || ""} ${cl.clause_pattern || ""} ${cl.explanation || ""}`;
      const match = qKeywords.filter((kw) => p.includes(kw)).length;
      if (match >= 1) {
        relevantLegalRef = cl.legal_reference || cl.source || "";
        relevantExplanation = cl.explanation || "";
        break;
      }
    }
  }
  if (bestSentence) {
    let ans = `\u0628\u0646\u0627\u0621\u064B \u0639\u0644\u0649 \u0646\u0635 \u0627\u0644\u0645\u0633\u062A\u0646\u062F \u0627\u0644\u0645\u0631\u0641\u0642:
"${bestSentence}"

`;
    if (relevantExplanation) {
      ans += `\u0627\u0644\u0634\u0631\u062D \u0648\u0627\u0644\u062A\u0648\u0636\u064A\u062D: ${relevantExplanation}

`;
    }
    if (relevantLegalRef) {
      ans += `\u0627\u0644\u0633\u0646\u062F \u0627\u0644\u0642\u0627\u0646\u0648\u0646\u064A \u0627\u0644\u0645\u0631\u062C\u0639\u064A: ${relevantLegalRef}

`;
    }
    ans += "\u0646\u0635\u064A\u062D\u0629 \u062F\u0644\u064A\u0644: \u064A\u064F\u0646\u0635\u062D \u062F\u0627\u0626\u0645\u064B\u0627 \u0628\u0645\u0631\u0627\u062C\u0639\u0629 \u0645\u062D\u0627\u0645\u064D \u0645\u062E\u062A\u0635 \u0641\u064A \u062D\u0627\u0644 \u0648\u062C\u0648\u062F \u0623\u064A \u0646\u0632\u0627\u0639 \u0623\u0648 \u0628\u0646\u062F \u063A\u064A\u0631 \u0648\u0627\u0636\u062D.";
    return ans;
  }
  if (relevantExplanation && relevantLegalRef) {
    return `\u0628\u0634\u0623\u0646 \u0627\u0633\u062A\u0641\u0633\u0627\u0631\u0643\u060C \u062A\u0648\u0636\u062D \u0627\u0644\u0642\u0648\u0627\u0639\u062F \u0627\u0644\u0642\u0627\u0646\u0648\u0646\u064A\u0629 \u0627\u0644\u0645\u0646\u0637\u0628\u0642\u0629 \u0627\u0644\u062A\u0627\u0644\u064A:
${relevantExplanation}

\u0627\u0644\u0645\u0627\u062F\u0629 \u0627\u0644\u0642\u0627\u0646\u0648\u0646\u064A\u0629: ${relevantLegalRef}

\u0646\u0635\u064A\u062D\u0629 \u062F\u0644\u064A\u0644: \u062A\u0623\u0643\u062F \u0645\u0646 \u0645\u0631\u0627\u062C\u0639\u0629 \u0627\u0644\u0628\u0646\u062F \u0627\u0644\u0645\u0642\u0627\u0628\u0644 \u0641\u064A \u0646\u0633\u062E\u062A\u0643 \u0645\u0646 \u0627\u0644\u0639\u0642\u062F \u0642\u0628\u0644 \u0627\u0644\u062A\u0648\u0642\u064A\u0639.`;
  }
  return `\u0628\u0646\u0627\u0621\u064B \u0639\u0644\u0649 \u0642\u0631\u0627\u0621\u0629 \u0627\u0644\u0645\u0633\u062A\u0646\u062F\u060C \u0644\u0645 \u064A\u062A\u0645 \u0627\u0644\u0639\u062B\u0648\u0631 \u0639\u0644\u0649 \u0646\u0635 \u0635\u0631\u064A\u062D \u0648\u0645\u0628\u0627\u0634\u0631 \u064A\u062C\u064A\u0628 \u0639\u0646 "${input.question}". \u064A\u064F\u0646\u0635\u062D \u0628\u0627\u0644\u062A\u0648\u0627\u0635\u0644 \u0645\u0639 \u0627\u0644\u0637\u0631\u0641 \u0627\u0644\u0622\u062E\u0631 \u0644\u062A\u0648\u0636\u064A\u062D \u0647\u0630\u0647 \u0627\u0644\u0646\u0642\u0637\u0629 \u0643\u062A\u0627\u0628\u0629 \u0641\u064A \u0627\u0644\u0639\u0642\u062F \u0623\u0648 \u0627\u0633\u062A\u0634\u0627\u0631\u0629 \u0645\u062D\u0627\u0645\u064D \u0645\u062E\u062A\u0635.`;
}

// server/api-entries/ask.ts
async function handler(req, res) {
  res.setHeader("Access-Control-Allow-Origin", "*");
  res.setHeader("Access-Control-Allow-Methods", "GET, POST, OPTIONS");
  res.setHeader("Access-Control-Allow-Headers", "Content-Type");
  if (req.method === "OPTIONS") {
    res.status(200).end();
    return;
  }
  if (req.method !== "POST") {
    res.status(200).json({ ok: true, message: "Dalil Ask Endpoint Ready" });
    return;
  }
  try {
    let body = req.body;
    if (typeof body === "string") {
      try {
        body = JSON.parse(body);
      } catch {
        body = {};
      }
    } else if (!body) {
      body = {};
    }
    const documentText = typeof body.documentText === "string" ? body.documentText : "";
    const question = typeof body.question === "string" ? body.question.trim() : "";
    if (!documentText.trim()) {
      res.status(400).json({ error: "\u0644\u0627 \u064A\u0648\u062C\u062F \u0645\u062D\u062A\u0648\u0649 \u0645\u0633\u062A\u0646\u062F \u0644\u0644\u0627\u0633\u062A\u0639\u0644\u0627\u0645 \u0639\u0646\u0647. \u0627\u0628\u062F\u0623 \u0628\u062A\u062D\u0644\u064A\u0644 \u0645\u0633\u062A\u0646\u062F \u0623\u0648\u0644\u0627\u064B." });
      return;
    }
    if (!question) {
      res.status(400).json({ error: "\u0627\u0643\u062A\u0628 \u0633\u0624\u0627\u0644\u0627\u064B \u0639\u0646 \u0627\u0644\u0645\u0633\u062A\u0646\u062F \u0623\u0648\u0644\u0627\u064B." });
      return;
    }
    const documentType = detectDocumentType(documentText);
    if (GEMINI_API_KEY && GEMINI_API_KEY !== "YOUR_GEMINI_API_KEY_HERE") {
      try {
        const groundContext = buildGroundingContext(documentType);
        const history = Array.isArray(body.history) ? body.history.filter((m) => m && (m.role === "user" || m.role === "model") && typeof m.text === "string").slice(-20).map((m) => ({ role: m.role, text: m.text })) : [];
        const answer = await askDocument({
          documentText,
          documentType,
          question,
          history,
          groundContext
        });
        res.status(200).json({ answer });
        return;
      } catch (geminiError) {
        console.warn("Gemini failed, using local QA:", geminiError);
      }
    }
    const localAnswer = askDocumentLocal({
      documentText,
      documentType,
      question
    });
    res.status(200).json({ answer: localAnswer });
  } catch (error) {
    console.error("Ask error:", error);
    res.status(500).json({ error: error?.message || "\u062D\u062F\u062B \u062E\u0637\u0623 \u0623\u062B\u0646\u0627\u0621 \u0627\u0644\u0625\u062C\u0627\u0628\u0629 \u0639\u0644\u0649 \u0633\u0624\u0627\u0644\u0643." });
  }
}
export {
  handler as default
};
